[{"order":1,"type":"heading","text":"Mastering Middleware in Express.js: Built-in, Third-Party, and Custom Middleware"},{"order":2,"type":"paragraph","text":"Middleware functions are the backbone of any Express.js application. They are functions that have access to the request object (req), the response object (res), and the next middleware function in the application's request-response cycle. Understanding how to leverage built-in, third-party, and custom middleware is essential for building scalable Node.js applications."},{"order":3,"type":"subheading","text":"1. Built-in Middleware"},{"order":4,"type":"paragraph","text":"Express has built-in middleware functions to handle common tasks such as serving static files and parsing incoming request bodies. As of version 4.16.0, Express includes express.json() for parsing JSON payloads and express.urlencoded() for parsing URL-encoded payloads."},{"order":5,"type":"code","text":"const express = require('express');
const app = express();

// Built-in middleware to parse JSON and URL-encoded data
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// Built-in middleware to serve static files
app.use(express.static('public'));

app.post('/api/data', (req, res) => {
  res.json({ received: req.body });
});

app.listen(3000);"},{"order":6,"type":"subheading","text":"2. Third-Party Middleware"},{"order":7,"type":"paragraph","text":"Third-party middleware modules extend the capabilities of your Express application without requiring you to write everything from scratch. Popular examples include morgan for logging, cors for enabling Cross-Origin Resource Sharing, and helmet for securing HTTP headers."},{"order":8,"type":"code","text":"const express = require('express');
const morgan = require('morgan');
const cors = require('cors');
const app = express();

// Use third-party middleware
app.use(morgan('dev'));
app.use(cors());

app.get('/', (req, res) => {
  res.send('Third-party middleware in action!');
});

app.listen(3000);"},{"order":9,"type":"subheading","text":"3. Custom Middleware"},{"order":10,"type":"paragraph","text":"When built-in and third-party solutions do not meet your exact requirements, you can write custom middleware. A custom middleware function takes three main arguments: req, res, and next. You must either call next() to pass control to the subsequent middleware or end the response cycle."},{"order":11,"type":"code","text":"const express = require('express');
const app = express();

// Custom logging middleware
const requestLogger = (req, res, next) => {
  console.log("[${new Date().toISOString()}] ${req.method} request to ${req.url}");
  next();
};

// Custom authentication middleware
const requireAuth = (req, res, next) => {
  const token = req.headers['authorization'];
  if (token === 'secret-token') {
    next();
  } else {
    res.status(401).json({ error: 'Unauthorized Access' });
  }
};

app.use(requestLogger);

app.get('/protected', requireAuth, (req, res) => {
  res.json({ message: 'Welcome to the protected route!' });
});

app.listen(3000);"},{"order":12,"type":"subheading","text":"Summary of Best Practices"},{"order":13,"type":"bullet_point","text":"Order matters: Place your middleware in the correct sequence (e.g., body parsers before route handlers)."},{"order":14,"type":"bullet_point","text":"Always invoke next() unless you are intentionally terminating the request-response cycle."},{"order":15,"type":"bullet_point","text":"Keep custom middleware modular by placing them in separate files and importing them into your main application entry point."}]
